"use client";
import { useState } from "react";
import { ArrowLeft, BarChart3, CalendarDays, CheckCircle2, ClipboardCheck, Download, HeartPulse, Info, MessageCircle, Plus, ShieldCheck, SlidersHorizontal, Sparkles, Users, Wallet } from "lucide-react";
import { useWorkspace } from "@/components/workspace-context";
import { Avatar, EmptyState, PageHeading } from "@/components/ui";
import { dateFa, fa, money, todayISO } from "@/lib/types";
import { percentComplete, strategyLabels } from "@/lib/talent-types";
import { useTalent } from "./context";
import { EntityActions, Progress, SectionHead, StateTag, TalentSearch, TalentStats, TalentTabs } from "./shared";

export function PulsePage() {
  const { data, open } = useTalent(); const { data: workspace } = useWorkspace(); const admin = workspace.user.role === "admin", manage = admin || workspace.user.role === "manager"; const [tab, setTab] = useState("surveys"); const [query, setQuery] = useState(""); const latest = data.metrics.find(m => m.reportReady);
  return <div className="tl-page page-enter"><PageHeading eyebrow="صدای همکاران، مسیر بهتر شدن" title="نبض سازمان" subtitle="گوش می‌دهیم، یاد می‌گیریم و با هم تجربه همکاری را بهتر می‌کنیم.">{manage && <a className="btn secondary" href="/api/talent/export?type=pulse"><Download size={16} />گزارش تجمیعی</a>}{admin && <button className="btn primary" onClick={() => open("survey")}><Plus size={16} />نظرسنجی جدید</button>}</PageHeading><div className="tl-pulse-banner"><div className="tl-pulse-visual"><HeartPulse size={35} strokeWidth={1.5} /><svg viewBox="0 0 230 45" aria-hidden="true"><path d="M0 25H50L60 14L74 35L90 3L110 43L124 19L135 25H230" /></svg></div><div><h2>حالِ خوب تیم، از شنیده‌شدن شروع می‌شود.</h2><p>پاسخ‌ها بدون نام گزارش می‌شوند. هر بازخورد، فرصتی برای یک تغییر واقعی است.</p></div><ShieldCheck size={26} /></div>
    {manage && <TalentStats items={[{ title: "نظرسنجی‌های فعال", value: data.surveys.filter(s => s.status === "active").length, icon: HeartPulse }, { title: "پاسخ‌های دریافت‌شده", value: data.metrics.reduce((n, m) => n + m.responses, 0), icon: MessageCircle, color: "blue" }, { title: "امتیاز آخرین دوره", value: latest?.score !== null && latest?.score !== undefined ? `${fa(latest.score)} / ۱۰۰` : "—", detail: "گزارش بسته‌شده و قابل انتشار", icon: BarChart3, color: "purple" }, { title: "اقدام‌های در جریان", value: data.improvements.filter(i => i.status !== "done").length, icon: ClipboardCheck, color: "orange" }]} />}
    <section className="card tl-workspace"><TalentTabs active={tab} onChange={setTab} tabs={[{ id: "surveys", label: "نظرسنجی‌ها" }, { id: "actions", label: "اقدام‌های بهبود", count: data.improvements.length }]} /><TalentSearch value={query} onChange={setQuery} placeholder="جستجو در نبض سازمان...">{tab === "actions" && manage && <button className="btn small primary tl-toolbar-end" onClick={() => open("improvement")}><Plus size={14} />اقدام تازه</button>}</TalentSearch><div className="tl-padded">
    {tab === "surveys" ? <div className="tl-survey-grid">{data.surveys.filter(s => s.title.includes(query)).map(s => { const m = data.metrics.find(m => m.surveyId === s.id)!; const expired = s.deadline < todayISO(); return <article className="tl-survey-card" key={s.id}><div className="tl-survey-top"><span className={`tl-module-icon ${s.status === "closed" ? "purple" : "teal"}`}><HeartPulse size={24} /></span><StateTag status={s.status} /></div><h3>{s.title}</h3><p>{s.description}</p><div className="tl-survey-meta"><span><Users size={13} />{s.department === "all" ? "همه همکاران" : s.department}</span><span><CalendarDays size={13} />تا {dateFa(s.deadline)}</span></div>{manage && <><div className="tl-plan-summary"><span>میزان مشارکت</span><span>{fa(m.responses)} از {fa(m.audience)} نفر</span></div><Progress value={percentComplete(m.responses, m.audience)} /></>}<div className="tl-survey-bottom"><div>{m.eligible && s.status === "active" && !expired && !m.participated && <button className="btn small primary" onClick={() => open("survey-response", s)}>صدای من<ArrowLeft size={13} /></button>}{m.participated && <span className="badge green"><CheckCircle2 size={13} />پاسخ شما ثبت شده</span>}{manage && s.status === "closed" && <button className="text-button" onClick={() => open("survey-report", s)}>مشاهده گزارش<ArrowLeft size={14} /></button>}{!manage && s.status === "closed" && <span className="muted">این دوره پایان یافته است</span>}{expired && s.status === "active" && <span className="badge gray">مهلت پاسخ پایان یافته</span>}</div><div className="row-actions">{admin && s.status === "draft" && <><button className="btn small soft" onClick={() => open("confirm", { action: "survey.publish", id: s.id, title: "انتشار نظرسنجی", description: "فهرست کارکنان فعال در لحظه انتشار ثبت می‌شود و پرسش‌ها دیگر قابل تغییر نیستند. منتشر شود؟" })}>انتشار</button><EntityActions kind="survey" item={s} deleteAction="survey.delete" /></>}{admin && s.status === "closed" && <button className="text-button" onClick={() => open("survey", { ...s, id: undefined, title: `${s.title} — دوره جدید`, deadline: new Date(Date.now() + 14 * 86400000).toISOString().slice(0, 10) })}>تکرار نظرسنجی</button>}{admin && s.status === "active" && <button className="text-button" onClick={() => open("confirm", { action: "survey.close", id: s.id, title: "پایان نظرسنجی", description: "پاسخ‌گویی بسته می‌شود و گزارش گروه‌های دارای حداقل ۵ پاسخ قابل مشاهده خواهد شد. ادامه می‌دهید؟" })}>پایان دوره</button>}</div></div></article>; })}</div> : data.improvements.length ? <div className="tl-action-list">{data.improvements.filter(i => i.title.includes(query)).map(i => <div className="tl-action-row" key={i.id}><span className={`tl-action-check ${i.status === "done" ? "done" : ""}`}><CheckCircle2 size={20} /></span><div><h3>{i.title}</h3><p>{i.notes}</p><small>{data.surveys.find(s => s.id === i.surveyId)?.title}</small></div><div className="tl-action-owner"><Avatar employee={workspace.employees.find(e => e.id === i.employeeId)} size="small" /><span>{workspace.employees.find(e => e.id === i.employeeId)?.name}<small>{dateFa(i.dueDate)}</small></span></div><StateTag status={i.status} /><EntityActions kind="improvement" item={i} deleteAction="improvement.delete" canEdit={manage} /></div>)}</div> : <EmptyState title="هر بازخورد می‌تواند شروع یک تغییر باشد" description="از نتایج نظرسنجی، یک اقدام مشخص با مسئول و مهلت بسازید." action={manage ? "تعریف اقدام بهبود" : undefined} onAction={() => open("improvement")} />}
    {!data.surveys.some(s => s.title.includes(query)) && tab === "surveys" && <EmptyState title={query ? "نظرسنجی‌ای با این عنوان پیدا نشد" : "هنوز نظرسنجی‌ای منتشر نشده"} description="نظرسنجی‌های متناسب با واحد شما اینجا نمایش داده می‌شوند." />}</div></section><div className="calculation-note"><ShieldCheck size={18} /><p>گزارش بی‌نام: نتایج فردی و نام پاسخ‌دهندگان در پنل نمایش داده نمی‌شود. گزارش‌ها تنها پس از پایان دوره و با حداقل ۵ پاسخ در هر گروه قابل مشاهده‌اند. این پرسش‌نامه‌های داخلی، ابزار تشخیص پزشکی یا آزمون روان‌شناختی استاندارد نیستند.</p></div></div>;
}

export function CompensationPage() {
  const { data, open } = useTalent(); const { data: workspace } = useWorkspace(); const [tab, setTab] = useState("policies"); const [query, setQuery] = useState(""); const staff = workspace.employees.filter(e => ["active", "on_leave"].includes(e.status)); const budget = staff.reduce((n, e) => n + e.baseSalary, 0); const recent = data.scenarios[0]; const proposed = recent?.entries.reduce((n, e) => n + e.proposed, 0) || 0;
  const million = (n: number) => `${new Intl.NumberFormat("fa-IR", { maximumFractionDigits: 1 }).format(n / 1000000)} میلیون`;
  return <div className="tl-page page-enter"><PageHeading eyebrow="تصمیم شفاف، پرداخت منصفانه‌تر" title="دستیار تعیین حقوق" subtitle="بازه‌های داخلی را تعریف کنید، اثر تصمیم‌ها را ببینید و آگاهانه تأیید کنید."><button className="btn secondary" onClick={() => open("policy")}><SlidersHorizontal size={16} />سیاست پرداخت</button><button className="btn primary" onClick={() => open("simulate")}><Sparkles size={16} />محاسبه سناریو</button></PageHeading><div className="tl-salary-notice"><span><Info size={21} /></span><div><strong>یک دستیار شفاف، نه یک جعبه سیاه</strong><p>پیشنهادها بر اساس حقوق فعلی و بازه‌های داخلیِ واردشده توسط شما محاسبه می‌شوند. اتصال به داده بازار جاب‌ویژن یا مدل هوش مصنوعی فعال نیست.</p></div><span className="badge blue">محاسبات قاعده‌محور</span></div>
    <TalentStats items={[{ title: "بودجه پایه ماهانه فعلی", value: million(budget), detail: "تومان · بدون مزایا و کسورات", icon: Wallet }, { title: "همکاران فعال در محاسبه", value: staff.length, icon: Users, color: "blue" }, { title: "سیاست‌های واحدها", value: data.policies.length, icon: SlidersHorizontal, color: "purple" }, { title: "سناریوهای در انتظار تأیید", value: data.scenarios.filter(s => s.status === "draft").length, icon: ClipboardCheck, color: "orange" }]} />
    <section className="card tl-workspace"><TalentTabs active={tab} onChange={setTab} tabs={[{ id: "policies", label: "سیاست تیم‌های سازمان" }, { id: "scenarios", label: "سناریوها و مقایسه", count: data.scenarios.length }, { id: "method", label: "روش محاسبه" }]} />{tab !== "method" && <TalentSearch value={query} onChange={setQuery} placeholder="جستجوی واحد یا سناریو..." />}
    {tab === "policies" ? <div className="table-scroll"><table className="data-table tl-policy-table"><thead><tr><th>واحد سازمانی</th><th>بازه داخلی <small>(میلیون تومان)</small></th><th>استراتژی</th><th>افزایش هدف</th><th>پیچیدگی</th><th /></tr></thead><tbody>{data.policies.filter(p => p.department.includes(query)).map(p => <tr key={p.id}><td><strong>{p.department}</strong><small className="tl-cell-sub">{fa(staff.filter(e => e.department === p.department).length)} همکار</small></td><td><div className="tl-salary-range"><span>{fa(p.minimum / 1000000)}</span><i><b style={{ right: `${(p.midpoint - p.minimum) / Math.max(1, p.maximum - p.minimum) * 100}%` }} /></i><span>{fa(p.maximum / 1000000)}</span></div><small className="tl-cell-sub">میانه: {fa(p.midpoint / 1000000)}</small></td><td><span className="badge blue">{strategyLabels[p.strategy]}</span></td><td>{fa(p.increasePercent)}٪</td><td>{fa(p.complexityPercent)}٪</td><td><EntityActions kind="policy" item={p} /></td></tr>)}</tbody></table></div> : tab === "scenarios" ? <div className="tl-padded">{data.scenarios.length ? <div className="tl-scenario-list">{data.scenarios.filter(s => s.title.includes(query)).map(s => { const current = s.entries.reduce((n, e) => n + e.current, 0); const next = s.entries.reduce((n, e) => n + e.proposed, 0); return <article key={s.id} className="tl-scenario-card"><div className="tl-section-head"><div><h3>{s.title}</h3><p>{s.createdBy} · {dateFa(s.createdAt)} · {fa(s.entries.length)} همکار</p></div><StateTag status={s.status} /></div><div className="tl-scenario-numbers"><span>بودجه مبنا<strong>{million(current)} <small>تومان</small></strong></span><ArrowLeft size={19} /><span>بودجه پیشنهادی<strong>{million(next)} <small>تومان</small></strong></span><span className="tl-change">+{fa(Math.round((next - current) / Math.max(1, current) * 100))}٪<small>تغییر بودجه</small></span></div><div className="tl-job-bottom"><button className="text-button" onClick={() => open("scenario-detail", s)}>بررسی و مقایسه همکاران<ArrowLeft size={14} /></button>{s.status === "draft" && <EntityActions kind="rename" item={s} deleteAction="salary.delete" />}</div></article>; })}</div> : <EmptyState title="قبل از تصمیم، اثر آن را ببینید" description="اولین سناریو را بر اساس سیاست تیم‌ها محاسبه کنید. هیچ تغییری بدون تأیید مدیر اعمال نمی‌شود." action="محاسبه سناریو" onAction={() => open("simulate")} icon={Sparkles} />}</div> : <div className="tl-method"><h3>چطور به عدد پیشنهادی می‌رسیم؟</h3><ol><li><strong>انتخاب نقطه مبنا:</strong> کف، میانه، میانگین میانه و سقف، یا سقف بازه داخلی بر اساس استراتژی واحد.</li><li><strong>اعمال پیچیدگی:</strong> ضرب نقطه مبنا در ضریب پیچیدگی واحد.</li><li><strong>مقایسه با افزایش هدف:</strong> بیشینه عدد مبنا و حقوق فعلی پس از افزایش هدف انتخاب می‌شود.</li><li><strong>کنترل سقف و عدم کاهش:</strong> نتیجه در سقف تعدیل‌شده محدود می‌شود؛ حقوق فعلی کاهش نمی‌یابد و عدد به نزدیک‌ترین هزار تومان گرد می‌شود.</li><li><strong>بازبینی انسانی:</strong> تأیید مدیر سیستم، حقوق پایه را تغییر می‌دهد؛ فیش‌های قبلی دست‌نخورده می‌مانند.</li></ol><div className="inline-info"><Info size={18} />افزایش هدف تضمین‌شده نیست و ممکن است به سقف بازه محدود شود. ارقام باید پیش از اعمال با مقررات جاری و توافق‌های قراردادی تطبیق داده شوند.</div></div>}</section></div>;
}
