"use client";
import { useState } from "react";
import { ArrowLeft, BookOpen, CalendarCheck2, CalendarDays, CheckCircle2, ClipboardList, Clock3, Download, GraduationCap, Layers, Plus, Rocket, Sparkles, Users } from "lucide-react";
import { useWorkspace } from "@/components/workspace-context";
import { Avatar, EmptyState, PageHeading } from "@/components/ui";
import { dateFa, fa, todayISO } from "@/lib/types";
import { percentComplete, taskRoleLabels } from "@/lib/talent-types";
import { useTalent } from "./context";
import { EntityActions, Progress, SectionHead, StateTag, TalentSearch, TalentStats, TalentTabs } from "./shared";
export function OnboardingPage() {
  const { data, open } = useTalent(); const { data: workspace } = useWorkspace(); const [tab, setTab] = useState("plans"); const [query, setQuery] = useState(""); const admin = workspace.user.role === "admin", manage = admin || workspace.user.role === "manager";
  const complete = data.plans.filter(p => data.tasks.filter(t => t.planId === p.id).length && data.tasks.filter(t => t.planId === p.id).every(t => t.done));
  return <div className="tl-page page-enter"><PageHeading eyebrow="یک شروع خوب، یک همراهی ماندگار" title={manage ? "آنبوردینگ و مسیر ورود" : "به خانواده آبان خوش آمدید"} subtitle="هیچ قدمی فراموش نمی‌شود؛ برنامه روزهای اول همکاری، روشن و قابل پیگیری.">{admin && <button className="btn secondary" onClick={() => open("template")}><Layers size={16} />الگوی جدید</button>}{manage && <button className="btn primary" onClick={() => open("plan")}><Plus size={16} />آغاز برنامه ورود</button>}</PageHeading>
    <div className="tl-onboarding-banner"><div><span className="eyebrow">همراه همکاران جدید، از اولین روز</span><h2>شروع‌های کوچک، تجربه‌های بزرگ.</h2><p>تیم منابع انسانی، مدیر واحد و همکار تازه‌وارد؛ هر کس سهم خودش را می‌داند.</p></div><div className="tl-orbit-illustration"><span><Rocket size={40} strokeWidth={1.2} /></span><i><CheckCircle2 size={19} /></i><b><Sparkles size={21} /></b></div></div>
    <TalentStats items={[{ title: "مسیرهای ورود", value: data.plans.length, icon: Rocket }, { title: "وظایف تکمیل‌شده", value: data.tasks.filter(t => t.done).length, detail: `از ${fa(data.tasks.length)} وظیفه تعریف‌شده`, icon: CheckCircle2, color: "blue" }, { title: "در انتظار پیگیری", value: data.tasks.filter(t => !t.done && t.dueDate < todayISO()).length, detail: "مهلت انجام گذشته است", icon: Clock3, color: "orange" }, { title: "شروع‌های موفق", value: complete.length, icon: Users, color: "purple" }]} />
    <section className="card tl-workspace"><TalentTabs active={tab} onChange={setTab} tabs={[{ id: "plans", label: manage ? "برنامه همکاران" : "برنامه‌های من" }, ...(manage ? [{ id: "templates", label: "کتابخانه الگوها" }] : [])]} /><TalentSearch value={query} onChange={setQuery} placeholder="جستجو در مسیرهای ورود..." />
      <div className="tl-padded">{tab === "plans" ? <div className="tl-plan-grid">{data.plans.filter(p => `${p.title} ${workspace.employees.find(e => e.id === p.employeeId)?.name}`.includes(query)).map(p => { const e = workspace.employees.find(e => e.id === p.employeeId); const tasks = data.tasks.filter(t => t.planId === p.id); const done = tasks.filter(t => t.done).length; return <article className="tl-plan-card" key={p.id}><div className="tl-plan-top"><Avatar employee={e} /><div><h3>{e?.name || "همکار آبان"}</h3><p>{e?.position}</p></div><span className={`badge ${done === tasks.length ? "green" : "blue"}`}>{done === tasks.length ? "تکمیل شده" : "در مسیر همراهی"}</span></div><h4>{p.title}</h4><div className="tl-plan-summary"><span>{fa(done)} از {fa(tasks.length)} قدم برداشته شده</span><span>{dateFa(p.startDate)}</span></div><Progress value={percentComplete(done, tasks.length)} /><div className="tl-owner-chips">{Object.entries(taskRoleLabels).map(([role, label]) => <span key={role}><i />{label}</span>)}</div><div className="tl-job-bottom"><button className="text-button" onClick={() => open("plan-detail", p)}>ادامه مسیر ورود<ArrowLeft size={14} /></button>{manage && <EntityActions kind="plan-edit" item={p} deleteAction="plan.delete" />}</div></article>; })}</div> : <div className="tl-template-grid">{data.templates.filter(t => t.title.includes(query)).map(t => <article className="tl-template-card" key={t.id}><span className="tl-module-icon teal"><Layers size={24} /></span><h3>{t.title}</h3><p>{t.department === "all" ? "قابل استفاده برای تمام واحدها" : t.department}</p><div className="tl-template-tasks">{t.tasks.slice(0, 3).map((task, i) => <span key={i}><CheckCircle2 size={13} />{task.title}</span>)}{t.tasks.length > 3 && <small>و {fa(t.tasks.length - 3)} قدم دیگر...</small>}</div><div className="tl-job-bottom"><button className="text-button" onClick={() => open("plan", undefined, { templateId: t.id })}>استفاده از الگو<ArrowLeft size={13} /></button><EntityActions kind="template" item={t} deleteAction="template.delete" canEdit={admin} /></div></article>)}</div>}
      {tab === "plans" && !data.plans.some(p => `${p.title} ${workspace.employees.find(e => e.id === p.employeeId)?.name}`.includes(query)) && <EmptyState title={query ? "برنامه‌ای با این مشخصات پیدا نشد" : "برای یک شروع خوب آماده‌ایم"} description={manage ? "با انتخاب همکار و الگو، برنامه اختصاصی ورود بسازید." : "برنامه ورود شما پس از تخصیص منابع انسانی اینجا نمایش داده می‌شود."} action={manage ? "آغاز برنامه ورود" : undefined} onAction={() => open("plan")} />}</div></section></div>;
}
export function LearningPage() {
  const { data, open, mutate } = useTalent(); const { data: workspace } = useWorkspace(); const [tab, setTab] = useState("library"); const [query, setQuery] = useState(""); const admin = workspace.user.role === "admin", manage = admin || workspace.user.role === "manager";
  const completed = data.enrollments.filter(e => e.status === "completed"); const enrolledCourseIds = new Set(data.enrollments.filter(e => e.employeeId === workspace.user.employeeId).map(e => e.courseId)); const courses = data.courses.filter(c => c.title.includes(query) && (tab !== "mine" || enrolledCourseIds.has(c.id)));
  return <div className="tl-page page-enter"><PageHeading eyebrow="هر روز، یک قدم رو به جلو" title="آکادمی آبان" subtitle="یادگیری در جریان کار؛ دوره‌های داخلی، مسیر رشد و کارنامه هر همکار."><a className="btn secondary" href="/api/talent/export?type=learning"><Download size={16} />گزارش آموزش</a>{admin && <button className="btn primary" onClick={() => open("course")}><Plus size={16} />دوره آموزشی جدید</button>}</PageHeading>
    <TalentStats items={[{ title: "دوره‌های در دسترس", value: data.courses.filter(c => c.status === "published").length, icon: BookOpen }, { title: "مسیرهای تخصیص‌یافته", value: data.enrollments.length, icon: Users, color: "blue" }, { title: "دوره‌های تکمیل‌شده", value: completed.length, icon: GraduationCap, color: "purple" }, { title: "نرخ تکمیل آموزش", value: `${fa(percentComplete(completed.length, data.enrollments.length))}٪`, icon: CheckCircle2, color: "orange" }]} />
    <section className="card tl-workspace"><TalentTabs active={tab} onChange={setTab} tabs={[{ id: "library", label: "کتابخانه یادگیری" }, ...(workspace.user.employeeId ? [{ id: "mine", label: "مسیرهای من" }] : []), ...(manage ? [{ id: "progress", label: "پیشرفت همکاران" }] : [])]} /><TalentSearch value={query} onChange={setQuery} placeholder="جستجوی دوره آموزشی...">{manage && <button className="btn small soft tl-toolbar-end" onClick={() => open("assign")}><Plus size={14} />تخصیص آموزش</button>}</TalentSearch>
    {tab !== "progress" ? <div className="tl-padded"><div className="tl-course-grid">{courses.map((c, index) => { const enrollment = data.enrollments.find(e => e.courseId === c.id && e.employeeId === workspace.user.employeeId); const colors = ["teal", "blue", "purple", "orange"]; return <article className="tl-course-card" key={c.id}><div className={`tl-course-art ${colors[index % 4]}`}><span className="tl-course-category">{c.category}</span><div className="tl-course-lines"><i /><i /><i /></div><BookOpen size={54} strokeWidth={1.05} /><small>{c.level}</small></div><div className="tl-course-content"><div className="tl-course-meta"><span><Clock3 size={13} />{fa(c.lessons.reduce((s, l) => s + l.minutes, 0))} دقیقه</span><span>{fa(c.lessons.length)} درس</span><StateTag status={c.status} /></div><h3>{c.title}</h3><p>{c.description}</p><span className="tl-course-instructor">{c.instructor}</span>{enrollment && <Progress value={percentComplete(enrollment.completedLessons.length, c.lessons.length)} />}<div className="tl-job-bottom"><button className="text-button" onClick={() => open("course-player", c)}>{enrollment?.status === "completed" ? "مشاهده کارنامه" : enrollment ? "ادامه یادگیری" : "مشاهده دوره"}<ArrowLeft size={14} /></button><div className="row-actions">{manage && c.status === "published" && <button className="icon-button" title="تخصیص دوره" aria-label={`تخصیص ${c.title}`} onClick={() => open("assign", undefined, { courseId: c.id })}><Users size={17} /></button>}{admin && <button className="icon-button" title="ساخت نسخه تازه" aria-label={`ساخت نسخه تازه از ${c.title}`} onClick={() => open("course", { ...c, id: undefined, title: `${c.title} (نسخه جدید)`, status: "draft" })}><Layers size={16} /></button>}<EntityActions kind="course" item={c} deleteAction="course.delete" canEdit={admin} /></div></div></div></article>; })}</div>{!courses.length && <EmptyState title="مسیر یادگیری تازه‌ای انتخاب کنید" description="دوره‌های تخصیص‌یافته یا متناسب با جستجوی شما اینجا نمایش داده می‌شوند." />}</div> : <div className="table-scroll"><table className="data-table"><thead><tr><th>همکار</th><th>دوره</th><th>پیشرفت</th><th>مهلت</th><th>کارنامه</th><th /></tr></thead><tbody>{data.enrollments.filter(e => data.courses.find(c => c.id === e.courseId)?.title.includes(query)).map(e => { const employee = workspace.employees.find(x => x.id === e.employeeId); const course = data.courses.find(c => c.id === e.courseId); return <tr key={e.id}><td><div className="person-cell"><Avatar employee={employee} /><span><strong>{employee?.name}</strong><small>{employee?.department}</small></span></div></td><td>{course?.title || "دوره بایگانی‌شده"}</td><td><Progress value={percentComplete(e.completedLessons.length, course?.lessons.length || 0)} /></td><td>{dateFa(e.dueDate)}</td><td>{e.score === null ? <StateTag status={e.status} /> : <span className={`badge ${e.status === "completed" ? "green" : "amber"}`}>{fa(e.score)} از ۱۰۰</span>}</td><td>{e.status !== "completed" && <button className="text-button" onClick={() => open("confirm", { action: "enrollment.delete", id: e.id, title: "لغو تخصیص آموزش", description: "این تخصیص و پیشرفت غیرنهایی آن حذف شود؟" })}>لغو تخصیص</button>}</td></tr>; })}</tbody></table></div>}</section><p className="tl-page-note">محتوای این کتابخانه داخلی و نمونه است؛ اشتراک مکتب‌خونه یا محتوای آموزشی دارای مجوز به آن متصل نیست.</p></div>;
}
